// Verify page: landscapes generated by the Python package next to the same seeds generated in the browser,
// with the differences measured (height map and every colour pixel).
import { route, api, app, esc, list, isStatic, needsServer, onLeave } from './core.js';
import { generate, cancel } from './terrain_client.js';
import { hexToRgb } from './terrain_biomes.js';

function pyColors(ref) {
  const n2 = ref.colors.length, out = new Uint8ClampedArray(n2 * 4), pal = ref.palette.map(hexToRgb);
  for (let k = 0; k < n2; k++) { const c = pal[ref.colors.charCodeAt(k) - 65]; out.set(c, 4 * k); out[4 * k + 3] = 255; }
  return out;
}

function put(canvas, rgba, n) {
  canvas.width = n; canvas.height = n;
  canvas.getContext('2d').putImageData(new ImageData(rgba, n, n), 0, 0);
}

export function compare(ref, L) {
  let maxDiff = 0, same = 0;
  const py = pyColors(ref), n2 = ref.height.length;
  for (let k = 0; k < n2; k++) {
    maxDiff = Math.max(maxDiff, Math.abs(ref.height[k] - L.height[k]));
    if (py[4 * k] === L.color[4 * k] && py[4 * k + 1] === L.color[4 * k + 1] && py[4 * k + 2] === L.color[4 * k + 2]) same++;
  }
  return { maxDiff, same, n2, py };
}

async function showCase(host, ref, alive) {
  const n = ref.params.size;
  host.innerHTML = `<h2>${esc(ref.name)}</h2>
    <p class="small mute">seed ${ref.seed} · ${n} x ${n} · ${esc(ref.params.season)} · density ${ref.params.feature_density}
    · octaves ${ref.params.octaves} · sea level ${ref.params.sea_level}</p>
    <div class="pair"><figure><canvas role="img" aria-label="Python result"></canvas><figcaption>Python (terrain package)</figcaption></figure>
    <figure><canvas role="img" aria-label="JavaScript result"></canvas><figcaption>JavaScript (this browser)</figcaption></figure></div>
    <p class="res">Generating in JavaScript...</p>`;
  const [cp, cj] = host.querySelectorAll('canvas');
  put(cp, pyColors(ref), n);
  const L = await generate(ref.params, ref.seed);
  if (!alive()) return;
  put(cj, new Uint8ClampedArray(L.color), n);
  const r = compare(ref, L);
  const ok = r.same === r.n2 && r.maxDiff < 1e-9;
  host.querySelector('.res').innerHTML = `<span class="${ok ? 'ok' : 'err'}">${ok ? 'Match' : 'Differs'}</span>:
    largest height difference ${r.maxDiff.toExponential(1)} (Python values sent with 12 significant digits);
    ${r.same} of ${r.n2} colour pixels identical.`;
}

route('verify', async () => {
  let alive = true;
  onLeave(() => { alive = false; cancel(); });
  const cases = await api('/reference');
  app().innerHTML = `
  <h1 class="glow">Python vs JavaScript</h1>
  <p class="lead">Each landscape below was generated by the Python package (<code>terrain.pipeline.generate_landscape</code>)
  and again by the JavaScript port in this browser, from the same seed and parameters.</p>
  <div class="callout a"><p>The port reproduces NumPy's random generator bit for bit (SeedSequence, PCG64, the
  ziggurat normal sampler), then the sine-wave noise, SciPy's Gaussian filter, the Voronoi feature regions, the
  rasteriser, seasonal effects and biome colours, in the same order. Remaining differences in the height map are
  rounding in the last digits of <code>sin</code>, <code>cos</code> and <code>exp</code>.</p></div>
  <div id="cases">${list(cases, c => `<section class="panel vcase" id="case-${esc(c.name)}"></section>`)}</div>
  <h2>Your own parameters</h2>
  <div id="custom"></div>`;
  const custom = document.getElementById('custom');
  if (isStatic()) custom.innerHTML = needsServer('Comparing arbitrary parameters with Python');
  else {
    const lim = await api('/limits');
    custom.innerHTML = `<div class="row narrow"><div><label for="v-seed">Seed</label><input id="v-seed" type="number" min="0" value="1234"></div>
      <div><label for="v-size">Size (max ${lim.reference_max_size})</label><input id="v-size" type="number" min="16" max="${lim.reference_max_size}" value="64"></div>
      <div><label for="v-season">Season</label><select id="v-season"><option>spring</option><option selected>summer</option><option>fall</option><option>winter</option></select></div>
      <button id="v-go" type="button">Compare</button></div><section class="panel vcase" id="v-out" hidden></section>`;
    document.getElementById('v-go').addEventListener('click', async () => {
      const out = document.getElementById('v-out');
      out.hidden = false; out.innerHTML = '<p class="mute">Running the Python generator...</p>';
      try {
        const ref = await api('/generate', { body: { seed: +document.getElementById('v-seed').value,
          params: { size: +document.getElementById('v-size').value, season: document.getElementById('v-season').value } } });
        await showCase(out, ref, () => alive);
      } catch (e) { out.innerHTML = `<p class="err">${esc(e.message)}</p>`; }
    });
  }
  for (const c of cases) {
    if (!alive) return;
    const ref = await api('/reference/' + c.name);
    try { await showCase(document.getElementById('case-' + c.name), ref, () => alive); }
    catch (e) { if (!e.cancelled) throw e; }
  }
});
